@startuml

class Bus {
  + LineNumber : string
}

class Trajectory {
  + Status : string
}

class Line {
  + Category : string
}

class TownAuthority {
  + ApprovalStatus : string
}

class ApprovalProcedure {
  + Status : string
}

class MENSOUser {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class MENSOCard {
  + CardNumber : string
}

class Trip {
  + Date : date
  + Time : time
}

class MonthlyInvoice {
  + Month : string
  + TotalAmount : double
  + Discount : float
}

class Customer {
  + Name : string
}

Bus "0..*" -- "0..*" Trajectory : assigned to

Line "1" -- "1..*" Trajectory : groups

Trajectory "1" -- "0..*" ApprovalProcedure : undergoes

TownAuthority "1" -- "0..*" ApprovalProcedure : reviews

Trajectory "0..*" -- "0..1" Line : part of

MENSOUser "1" -- "1" MENSOCard : possesses

MENSOUser "1" -- "0..*" MonthlyInvoice : receives

MENSOUser "1" -- "0..*" Trip : performs

Line "1" -- "0..*" Trip : is traveled on

Trip "0..*" -- "1" MonthlyInvoice : is included in

Customer "1" -- "0..*" MonthlyInvoice : pays

@enduml

